# Build the 30x30 input from the transcribed repeated-tile center matrix, then bridge same-color centers horizontally/vertically through zeros only.
H=W=30
g=[[0]*W for _ in range(H)]
centers=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
# tile starts at 1,8,15,22,29; outer frame top/bottom/left/right colored 4, interior 3x3 color center
for tr in range(5):
  r0=1+7*tr
  for tc in range(5):
    c0=1+7*tc
    # bounds clipped to grid: 5x5 tile frame, but last row/col are only top/left edge visible
    for r in range(r0,min(r0+5,H)):
      for c in range(c0,min(c0+5,W)):
        if r==r0 or r==r0+4 or c==c0 or c==c0+4:
          g[r][c]=4
        else:
          # inner 3x3 center color from matrix for full cells; position center corresponds offset 2
          if tr<4 and tc<4:
            g[r][c]=centers[tr][tc]
# bridge each row/col for each color based on occurrences of that color at tile centers; fill zero cells strictly between first/last occurrence
out=[row[:] for row in g]
for r in range(H):
  for color in set(g[r]):
    inds=[c for c,v in enumerate(g[r]) if v==color and color not in (0,4)]
    if len(inds)>=2:
      for c in range(min(inds)+1,max(inds)):
        if out[r][c]==0: out[r][c]=color
for c in range(W):
  for color in set(g[r][c] for r in range(H)):
    inds=[r for r in range(H) if g[r][c]==color and color not in (0,4)]
    if len(inds)>=2:
      for r in range(min(inds)+1,max(inds)):
        if out[r][c]==0: out[r][c]=color
# output and validation
assert len(out)==30 and all(len(x)==30 for x in out)
print(out)
print('bridged cells',sum(a!=b for row1,row2 in zip(g,out) for a,b in zip(row1,row2)))

