from collections import defaultdict

def bridge_audit(grid):
    h,w=len(grid),len(grid[0]); masks=defaultdict(set)
    for r,row in enumerate(grid):
        for color in set(row):
            if color in (0,2): continue
            cols=[c for c,x in enumerate(row) if x==color]
            for c in range(min(cols),max(cols)+1):
                if grid[r][c]==2: masks[(r,c)].add(color)
    for c in range(w):
        colors={grid[r][c] for r in range(h)}-{0,2}
        for color in colors:
            rows=[r for r in range(h) if grid[r][c]==color]
            for r in range(min(rows),max(rows)+1):
                if grid[r][c]==2: masks[(r,c)].add(color)
    return {k:v for k,v in masks.items() if len(v)>1}

